import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import {
  FloatingPanel as FloatingPanelPrimitive,
  useFloatingPanel,
  useFloatingPanelContext,
} from '@ark-ui/solid/floating-panel';
import { clsx } from 'clsx';
import type { ComponentProps } from 'solid-js';
import { For, children, splitProps } from 'solid-js';
import { GripIcon, MaximizeIcon, MinusIcon, RestoreIcon } from '@/lib/moduix/icons/ui/Icons';
import {
  OverlayPortal,
  OverlayPortalProvider,
  type OverlayPortalProps,
} from '@/lib/moduix/overlayPortal';
import { CloseButton } from '../close-button';
import styles from './FloatingPanel.module.css';

const DEFAULT_CLOSE_BUTTON_LABEL = 'Close panel';
type FloatingPanelResizeTriggerAxis = NonNullable<
  ComponentProps<typeof FloatingPanelPrimitive.ResizeTrigger>['axis']
>;

const resizeTriggerAxes = [
  'n',
  'e',
  's',
  'w',
  'ne',
  'se',
  'sw',
  'nw',
] satisfies FloatingPanelResizeTriggerAxis[];

type FloatingPanelRootProps = ComponentProps<typeof FloatingPanelPrimitive.Root> &
  OverlayPortalProps;
type FloatingPanelRootProviderProps = ComponentProps<typeof FloatingPanelPrimitive.RootProvider> &
  OverlayPortalProps;
type FloatingPanelCloseIconProps = Omit<
  ComponentProps<typeof FloatingPanelPrimitive.CloseTrigger>,
  'asChild'
>;

function FloatingPanelRoot(props: FloatingPanelRootProps) {
  const [local, others] = splitProps(props, [
    'children',
    'closeOnEscape',
    'lazyMount',
    'persistRect',
    'portalled',
    'portalRef',
    'unmountOnExit',
  ]);

  return (
    <OverlayPortalProvider portalled={local.portalled} portalRef={local.portalRef}>
      <FloatingPanelPrimitive.Root
        closeOnEscape={local.closeOnEscape ?? true}
        lazyMount={local.lazyMount ?? true}
        persistRect={local.persistRect ?? true}
        unmountOnExit={local.unmountOnExit ?? true}
        {...others}
      >
        {local.children}
      </FloatingPanelPrimitive.Root>
    </OverlayPortalProvider>
  );
}

function FloatingPanelRootProvider(props: FloatingPanelRootProviderProps) {
  const [local, others] = splitProps(props, [
    'children',
    'lazyMount',
    'portalled',
    'portalRef',
    'unmountOnExit',
  ]);

  return (
    <OverlayPortalProvider portalled={local.portalled} portalRef={local.portalRef}>
      <FloatingPanelPrimitive.RootProvider
        lazyMount={local.lazyMount ?? true}
        unmountOnExit={local.unmountOnExit ?? true}
        {...others}
      >
        {local.children}
      </FloatingPanelPrimitive.RootProvider>
    </OverlayPortalProvider>
  );
}

function FloatingPanelTrigger(props: ComponentProps<typeof FloatingPanelPrimitive.Trigger>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <FloatingPanelPrimitive.Trigger
      asChild={local.asChild}
      class={clsx(!local.asChild && styles.trigger, local.class)}
      {...others}
      data-slot="floating-panel-trigger"
    />
  );
}

function FloatingPanelPositioner(props: ComponentProps<typeof FloatingPanelPrimitive.Positioner>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <OverlayPortal>
      <FloatingPanelPrimitive.Positioner
        class={clsx(styles.positioner, local.class)}
        {...others}
        data-slot="floating-panel-positioner"
      />
    </OverlayPortal>
  );
}

function FloatingPanelContent(props: ComponentProps<typeof FloatingPanelPrimitive.Content>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <FloatingPanelPrimitive.Content
      class={clsx(styles.content, local.class)}
      {...others}
      data-slot="floating-panel-content"
    />
  );
}

function FloatingPanelDragTrigger(
  props: ComponentProps<typeof FloatingPanelPrimitive.DragTrigger>,
) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <FloatingPanelPrimitive.DragTrigger
      class={clsx(styles.dragTrigger, local.class)}
      {...others}
      data-slot="floating-panel-drag-trigger"
    />
  );
}

function FloatingPanelHeader(props: ComponentProps<typeof FloatingPanelPrimitive.Header>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <FloatingPanelPrimitive.Header
      class={clsx(styles.header, local.class)}
      {...others}
      data-slot="floating-panel-header"
    />
  );
}

function FloatingPanelTitle(props: ComponentProps<typeof FloatingPanelPrimitive.Title>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <FloatingPanelPrimitive.Title
      class={clsx(styles.title, local.class)}
      {...others}
      data-slot="floating-panel-title"
    />
  );
}

function FloatingPanelControl(props: ComponentProps<typeof FloatingPanelPrimitive.Control>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <FloatingPanelPrimitive.Control
      class={clsx(styles.control, local.class)}
      {...others}
      data-slot="floating-panel-control"
    />
  );
}

function FloatingPanelStageTrigger(
  props: ComponentProps<typeof FloatingPanelPrimitive.StageTrigger>,
) {
  const [local, others] = splitProps(props, [
    'aria-label',
    'asChild',
    'children',
    'class',
    'stage',
  ]);
  const resolvedChildren = children(() => local.children);
  const shouldRenderDefaultIcon = () => local.children == null && !local.asChild;

  return (
    <FloatingPanelPrimitive.StageTrigger
      aria-label={local['aria-label']}
      asChild={local.asChild}
      class={clsx(!local.asChild && styles.controlButton, local.class)}
      stage={local.stage}
      {...others}
      data-slot="floating-panel-stage-trigger"
    >
      {resolvedChildren()}
      {shouldRenderDefaultIcon() && local.stage === 'minimized' ? <MinusIcon /> : null}
      {shouldRenderDefaultIcon() && local.stage === 'maximized' ? <MaximizeIcon /> : null}
      {shouldRenderDefaultIcon() && local.stage === 'default' ? <RestoreIcon /> : null}
    </FloatingPanelPrimitive.StageTrigger>
  );
}

function FloatingPanelCloseTrigger(
  props: ComponentProps<typeof FloatingPanelPrimitive.CloseTrigger>,
) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <FloatingPanelPrimitive.CloseTrigger
      asChild={local.asChild}
      class={clsx(!local.asChild && styles.controlButton, local.class)}
      {...others}
      data-slot="floating-panel-close-trigger"
    />
  );
}

function FloatingPanelCloseIcon(props: FloatingPanelCloseIconProps) {
  const [local, others] = splitProps(props, ['aria-label', 'aria-labelledby', 'children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <FloatingPanelPrimitive.CloseTrigger
      asChild={(triggerProps) => (
        <CloseButton.Root
          {...triggerProps()}
          data-slot="floating-panel-close-icon"
          aria-label={local['aria-label'] ?? DEFAULT_CLOSE_BUTTON_LABEL}
          aria-labelledby={local['aria-labelledby']}
          class={clsx(styles.controlButton, local.class)}
        >
          {resolvedChildren()}
        </CloseButton.Root>
      )}
      {...others}
    />
  );
}

function FloatingPanelBody(props: ComponentProps<typeof FloatingPanelPrimitive.Body>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <FloatingPanelPrimitive.Body
      class={clsx(styles.body, local.class)}
      {...others}
      data-slot="floating-panel-body"
    />
  );
}

function FloatingPanelFooter(props: HTMLArkProps<'div'>) {
  const [local, others] = splitProps(props, ['class']);
  const floatingPanel = useFloatingPanelContext();

  return (
    <ark.div
      {...others}
      data-slot="floating-panel-footer"
      data-minimized={
        (
          floatingPanel().getContentProps() as {
            'data-minimized'?: string;
          }
        )['data-minimized']
      }
      class={clsx(styles.footer, local.class)}
    />
  );
}

function FloatingPanelResizeTrigger(
  props: ComponentProps<typeof FloatingPanelPrimitive.ResizeTrigger>,
) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <FloatingPanelPrimitive.ResizeTrigger
      class={clsx(styles.resizeTrigger, local.class)}
      {...others}
      data-slot="floating-panel-resize-trigger"
    />
  );
}

function FloatingPanelResizeTriggerGroup(props: {
  axes?: readonly FloatingPanelResizeTriggerAxis[];
}) {
  return (
    <For each={props.axes ?? resizeTriggerAxes}>
      {(axis) => <FloatingPanelResizeTrigger axis={axis} />}
    </For>
  );
}

function FloatingPanelDragIndicator(props: ComponentProps<'span'>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <span
      aria-hidden="true"
      class={clsx(styles.dragIndicator, local.class)}
      {...others}
      data-slot="floating-panel-drag-indicator"
    >
      {resolvedChildren() ?? <GripIcon />}
    </span>
  );
}

type FloatingPanelComponent = typeof FloatingPanelRoot & {
  Context: typeof FloatingPanelPrimitive.Context;
  Root: typeof FloatingPanelRoot;
  RootProvider: typeof FloatingPanelRootProvider;
  Trigger: typeof FloatingPanelTrigger;
  Positioner: typeof FloatingPanelPositioner;
  Content: typeof FloatingPanelContent;
  DragTrigger: typeof FloatingPanelDragTrigger;
  Header: typeof FloatingPanelHeader;
  Title: typeof FloatingPanelTitle;
  Control: typeof FloatingPanelControl;
  StageTrigger: typeof FloatingPanelStageTrigger;
  CloseTrigger: typeof FloatingPanelCloseTrigger;
  CloseIcon: typeof FloatingPanelCloseIcon;
  Body: typeof FloatingPanelBody;
  Footer: typeof FloatingPanelFooter;
  ResizeTrigger: typeof FloatingPanelResizeTrigger;
  ResizeTriggerGroup: typeof FloatingPanelResizeTriggerGroup;
  DragIndicator: typeof FloatingPanelDragIndicator;
  useFloatingPanel: typeof useFloatingPanel;
  useFloatingPanelContext: typeof useFloatingPanelContext;
};

const FloatingPanel: FloatingPanelComponent = Object.assign(FloatingPanelRoot, {
  Context: FloatingPanelPrimitive.Context,
  Root: FloatingPanelRoot,
  RootProvider: FloatingPanelRootProvider,
  Trigger: FloatingPanelTrigger,
  Positioner: FloatingPanelPositioner,
  Content: FloatingPanelContent,
  DragTrigger: FloatingPanelDragTrigger,
  Header: FloatingPanelHeader,
  Title: FloatingPanelTitle,
  Control: FloatingPanelControl,
  StageTrigger: FloatingPanelStageTrigger,
  CloseTrigger: FloatingPanelCloseTrigger,
  CloseIcon: FloatingPanelCloseIcon,
  Body: FloatingPanelBody,
  Footer: FloatingPanelFooter,
  ResizeTrigger: FloatingPanelResizeTrigger,
  ResizeTriggerGroup: FloatingPanelResizeTriggerGroup,
  DragIndicator: FloatingPanelDragIndicator,
  useFloatingPanel,
  useFloatingPanelContext,
});

export { FloatingPanel, resizeTriggerAxes, useFloatingPanel, useFloatingPanelContext };
export type { FloatingPanelRootProps, FloatingPanelRootProviderProps };

@layer moduix.components {
  .trigger {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: var(--moduix-floating-panel-trigger-height, var(--moduix-size-md));
    margin: 0;
    padding: var(--moduix-floating-panel-trigger-padding-y, var(--moduix-spacing-1))
      var(--moduix-floating-panel-trigger-padding-x, var(--moduix-spacing-3));
    border: var(--moduix-floating-panel-trigger-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-floating-panel-trigger-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-floating-panel-trigger-radius, var(--moduix-radius-md));
    background-color: var(--moduix-floating-panel-trigger-bg, var(--moduix-color-background));
    color: var(--moduix-floating-panel-trigger-color, var(--moduix-color-foreground));
    font: inherit;
    font-size: var(--moduix-floating-panel-trigger-font-size, var(--moduix-text-md));
    line-height: var(
      --moduix-floating-panel-trigger-line-height,
      var(--moduix-line-height-text-md)
    );
    user-select: none;
    outline: 0;
    cursor: pointer;
    transition:
      background-color var(--moduix-floating-panel-transition, var(--moduix-transition-default)),
      border-color var(--moduix-floating-panel-transition, var(--moduix-transition-default)),
      color var(--moduix-floating-panel-transition, var(--moduix-transition-default)),
      opacity var(--moduix-floating-panel-transition, var(--moduix-transition-default));

    @media (hover: hover) {
      &:hover {
        background-color: var(--moduix-floating-panel-trigger-bg-hover, var(--moduix-color-accent));
      }
    }

    &:active,
    &[data-state='open'] {
      background-color: var(
        --moduix-floating-panel-trigger-bg-active,
        var(--moduix-floating-panel-trigger-bg-hover, var(--moduix-color-accent))
      );
    }
  }

  .positioner {
    z-index: var(--z-index, var(--moduix-floating-panel-z-index, var(--moduix-z-popup)));
    outline: 0;
  }

  .content {
    position: relative;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    min-width: var(--moduix-floating-panel-min-width, 16rem);
    min-height: var(--moduix-floating-panel-min-height, 10rem);
    overflow: hidden;
    border: var(--moduix-floating-panel-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-floating-panel-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-floating-panel-radius, var(--moduix-radius-md));
    background-color: var(--moduix-floating-panel-bg, var(--moduix-color-popover));
    color: var(--moduix-floating-panel-color, var(--moduix-color-popover-foreground));
    box-shadow: var(--moduix-floating-panel-shadow, var(--moduix-shadow-lg));
    outline: 0;
    transform-origin: var(--transform-origin);

    &[data-state='open'] {
      animation: floating-panel-enter
        var(
          --moduix-floating-panel-transition,
          var(--moduix-popup-motion-duration, var(--moduix-duration-fast))
            var(--moduix-popup-motion-easing, ease)
        )
        both;
    }

    &[data-state='closed'] {
      pointer-events: none;
      animation: floating-panel-exit
        var(
          --moduix-floating-panel-transition,
          var(--moduix-popup-motion-duration, var(--moduix-duration-fast))
            var(--moduix-popup-motion-easing, ease)
        )
        both;
    }

    &[data-behind] {
      opacity: var(--moduix-floating-panel-behind-opacity, 0.55);
    }

    &[data-minimized] {
      min-height: 0;
    }
  }

  .dragTrigger {
    display: block;
  }

  .header {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--moduix-floating-panel-header-gap, var(--moduix-spacing-3));
    min-height: var(--moduix-floating-panel-header-height, var(--moduix-size-xl));
    padding: var(--moduix-floating-panel-header-padding-y, var(--moduix-spacing-2))
      var(--moduix-floating-panel-header-padding-x, var(--moduix-spacing-3));
    border-bottom: var(--moduix-floating-panel-header-border-width, var(--moduix-border-width-sm))
      solid
      var(
        --moduix-floating-panel-header-border-color,
        var(--moduix-floating-panel-border-color, var(--moduix-color-border))
      );
    background-color: var(--moduix-floating-panel-header-bg, var(--moduix-color-muted));
    cursor: grab;
    user-select: none;

    &[data-dragging] {
      cursor: grabbing;
    }

    &[data-minimized] {
      border-bottom-color: transparent;
    }
  }

  .title {
    display: inline-flex;
    min-width: 0;
    align-items: center;
    gap: var(--moduix-floating-panel-title-gap, var(--moduix-spacing-2));
    margin: 0;
    color: var(
      --moduix-floating-panel-title-color,
      var(--moduix-floating-panel-color, var(--moduix-color-popover-foreground))
    );
    font-size: var(--moduix-floating-panel-title-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-floating-panel-title-font-weight, var(--moduix-weight-semibold));
    line-height: var(--moduix-floating-panel-title-line-height, var(--moduix-line-height-text-sm));
  }

  .control {
    display: inline-flex;
    flex: none;
    align-items: center;
    gap: var(--moduix-floating-panel-control-gap, var(--moduix-spacing-1));
  }

  .controlButton {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--moduix-floating-panel-control-size, var(--moduix-size-sm));
    height: var(--moduix-floating-panel-control-size, var(--moduix-size-sm));
    margin: 0;
    padding: 0;
    border: var(--moduix-floating-panel-control-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-floating-panel-control-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-floating-panel-control-radius, var(--moduix-radius-sm));
    background-color: var(--moduix-floating-panel-control-bg, var(--moduix-color-background));
    color: var(--moduix-floating-panel-control-color, var(--moduix-color-foreground));
    font: inherit;
    outline: 0;
    cursor: pointer;
    transition:
      background-color var(--moduix-floating-panel-transition, var(--moduix-transition-default)),
      border-color var(--moduix-floating-panel-transition, var(--moduix-transition-default)),
      color var(--moduix-floating-panel-transition, var(--moduix-transition-default)),
      opacity var(--moduix-floating-panel-transition, var(--moduix-transition-default));

    & > svg {
      width: var(--moduix-floating-panel-control-icon-size, var(--moduix-spacing-4));
      height: var(--moduix-floating-panel-control-icon-size, var(--moduix-spacing-4));
    }

    @media (hover: hover) {
      &:hover {
        background-color: var(--moduix-floating-panel-control-bg-hover, var(--moduix-color-accent));
      }
    }
  }

  .trigger:focus-visible,
  .controlButton:focus-visible {
    outline: var(
        --moduix-floating-panel-focus-ring-width,
        var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
      )
      solid var(--moduix-floating-panel-focus-ring-color, var(--moduix-color-ring));
    outline-offset: calc(
      var(
          --moduix-floating-panel-focus-ring-width,
          var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
        ) *
        -1
    );
  }

  .trigger:is([data-disabled], [disabled]),
  .controlButton:is([data-disabled], [disabled]) {
    pointer-events: none;
    opacity: var(--moduix-floating-panel-disabled-opacity, var(--moduix-opacity-disabled));
    cursor: default;
  }

  .dragIndicator {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    color: var(--moduix-floating-panel-drag-indicator-color, var(--moduix-color-muted-foreground));

    & > svg {
      width: var(--moduix-floating-panel-drag-indicator-size, var(--moduix-spacing-4));
      height: var(--moduix-floating-panel-drag-indicator-size, var(--moduix-spacing-4));
    }
  }

  .body {
    box-sizing: border-box;
    flex: 1 1 auto;
    min-height: 0;
    overflow: auto;
    padding: var(--moduix-floating-panel-body-padding, var(--moduix-spacing-4));
    color: var(
      --moduix-floating-panel-body-color,
      var(--moduix-floating-panel-color, var(--moduix-color-popover-foreground))
    );
    font-size: var(--moduix-floating-panel-body-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-floating-panel-body-line-height, var(--moduix-line-height-text-sm));

    &[data-minimized] {
      display: none;
    }
  }

  .footer {
    box-sizing: border-box;
    display: flex;
    flex: 0 0 auto;
    align-items: center;
    justify-content: var(--moduix-floating-panel-footer-justify, flex-end);
    gap: var(--moduix-floating-panel-footer-gap, var(--moduix-spacing-2));
    padding: var(--moduix-floating-panel-footer-padding-y, var(--moduix-spacing-2))
      var(--moduix-floating-panel-footer-padding-x, var(--moduix-spacing-3));
    border-top: var(--moduix-floating-panel-footer-border-width, var(--moduix-border-width-sm))
      solid
      var(
        --moduix-floating-panel-footer-border-color,
        var(--moduix-floating-panel-border-color, var(--moduix-color-border))
      );
    color: var(--moduix-floating-panel-footer-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-floating-panel-footer-font-size, var(--moduix-text-xs));
    line-height: var(--moduix-floating-panel-footer-line-height, var(--moduix-line-height-text-xs));

    &[data-minimized] {
      display: none;
    }
  }

  .resizeTrigger {
    position: absolute;

    &[data-axis='n'],
    &[data-axis='s'] {
      left: var(--moduix-spacing-3);
      width: calc(100% - (var(--moduix-spacing-3) * 2));
      height: var(--moduix-spacing-2);
    }

    &[data-axis='n'] {
      top: calc(var(--moduix-spacing-2) / -2);
    }

    &[data-axis='s'] {
      bottom: calc(var(--moduix-spacing-2) / -2);
    }

    &[data-axis='e'],
    &[data-axis='w'] {
      top: var(--moduix-spacing-3);
      width: var(--moduix-spacing-2);
      height: calc(100% - (var(--moduix-spacing-3) * 2));
    }

    &[data-axis='e'] {
      right: calc(var(--moduix-spacing-2) / -2);
    }

    &[data-axis='w'] {
      left: calc(var(--moduix-spacing-2) / -2);
    }

    &[data-axis='ne'],
    &[data-axis='nw'],
    &[data-axis='se'],
    &[data-axis='sw'] {
      width: var(--moduix-spacing-3);
      height: var(--moduix-spacing-3);
    }

    &[data-axis='ne'] {
      top: calc(var(--moduix-spacing-3) / -2);
      right: calc(var(--moduix-spacing-3) / -2);
    }

    &[data-axis='nw'] {
      top: calc(var(--moduix-spacing-3) / -2);
      left: calc(var(--moduix-spacing-3) / -2);
    }

    &[data-axis='se'] {
      right: calc(var(--moduix-spacing-3) / -2);
      bottom: calc(var(--moduix-spacing-3) / -2);
    }

    &[data-axis='sw'] {
      bottom: calc(var(--moduix-spacing-3) / -2);
      left: calc(var(--moduix-spacing-3) / -2);
    }

    &[data-disabled] {
      pointer-events: none;
    }
  }

  @keyframes floating-panel-enter {
    from {
      opacity: var(
        --moduix-floating-panel-starting-opacity,
        var(--moduix-popup-motion-starting-opacity, 0)
      );
      translate: var(
